3	/**
4	 * Host capacity accounting for the deploy flow.
5	 *
6	 * We oversell RAM (the scarce resource) by a factor, but never past the
7	 * host's physical RAM minus a reserve for the hypervisor itself. Disk on
8	 * `vmdata` is large relative to plan sizes, so RAM is the binding constraint.
9	 *
10	 * All values are overridable via env so staging/prod can differ without code
11	 * changes; the defaults match the production KS-GAME box (64 GB RAM).
12	 */
13	export const HOST_RAM_MB = Number(process.env.NXEON_HOST_RAM_MB ?? 64000);
14	export const HOST_RAM_RESERVE_MB = Number(process.env.NXEON_HOST_RAM_RESERVE_MB ?? 8000);
15	export const RAM_OVERSELL_FACTOR = Number(process.env.NXEON_RAM_OVERSELL ?? 1.5);
16	
17	/** Effective committable RAM ceiling in MB after reserve + oversell. */
18	export function ramCeilingMB(): number {
19	  return Math.max(0, (HOST_RAM_MB - HOST_RAM_RESERVE_MB) * RAM_OVERSELL_FACTOR);
20	}
21	
22	export type CapacitySnapshot = {
23	  committedRamMB: number;
24	  committedDiskGB: number;
25	  ceilingRamMB: number;
26	  serverCount: number;
27	  /** 0..1 fraction of the RAM ceiling already committed. */
28	  ramUtilization: number;
29	  /** true once committed RAM is within 15% of the ceiling. */
30	  nearCapacity: boolean;
31	};
32	
33	/** Sum committed RAM/disk across all servers that are not being torn down. */
34	export async function capacitySnapshot(): Promise<CapacitySnapshot> {
35	  const servers = await db.server.findMany({
36	    where: { status: { not: "DELETING" } },
37	    select: { plan: { select: { ramMB: true, diskGB: true } } },
38	  });
39	  const committedRamMB = servers.reduce((sum, s) => sum + s.plan.ramMB, 0);
40	  const committedDiskGB = servers.reduce((sum, s) => sum + s.plan.diskGB, 0);
41	  const ceilingRamMB = ramCeilingMB();
42	  const ramUtilization = ceilingRamMB > 0 ? committedRamMB / ceilingRamMB : 1;
43	  return {
44	    committedRamMB,
45	    committedDiskGB,
46	    ceilingRamMB,
47	    serverCount: servers.length,
48	    ramUtilization,
49	    nearCapacity: ramUtilization >= 0.85,
50	  };
51	}
52	
53	/**
54	 * Would deploying `planId` push committed RAM past the oversell ceiling?
55	 * Returns { ok:false, reason } when the host cannot take the new server.
56	 */
57	export async function capacityCheck(planId: string): Promise<{ ok: boolean; reason?: string }> {
58	  const plan = await db.plan.findUnique({ where: { id: planId }, select: { ramMB: true, name: true } });
59	  if (!plan) return { ok: false, reason: "Plan not found." };
60	
61	  const snap = await capacitySnapshot();
62	  const projected = snap.committedRamMB + plan.ramMB;
63	  if (projected > snap.ceilingRamMB) {
64	    return {
65	      ok: false,
66	      reason:
67	        "The host is at capacity — not enough RAM headroom to deploy this plan right now. " +
68	        "Please try a smaller plan or contact support.",
69	    };
70	  }
71	  return { ok: true };
72	}
