import { db } from "./db";
import { pve, node as primaryNode, pveFor } from "./proxmox";
import type { Node } from "@prisma/client";

/**
 * Shared, READ-ONLY monitoring helpers for Nxeon.
 *
 * Everything here is safe to call from server components (status page, admin
 * monitoring) and from the worker sweep (`worker/monitor.ts`). No mutations,
 * no secrets in the returned shapes — the public /status page renders off the
 * same `getHealth()` logic the API exposes.
 *
 * Proxmox access is strictly read-only: `GET /nodes/{node}/status` and
 * `GET /nodes/{node}/storage/{storage}/status` (+ backup content listing).
 */

export type CompStatus = "operational" | "degraded" | "down";
export type Component = { status: CompStatus; detail: string };

export type HealthReport = {
  web: Component;
  db: Component;
  worker: Component;
  proxmox: Component;
  checkedAt: string;
};

// ---- Thresholds (env-overridable) ---------------------------------------

/** Worker is expected to touch the queue within this window; older QUEUED work ⇒ down. */
export const WORKER_STALE_MS = Number(process.env.NXEON_WORKER_STALE_MS ?? 2 * 60_000);
/** A Job sitting in RUNNING longer than this is considered stuck. */
export const STUCK_JOB_MS = Number(process.env.NXEON_STUCK_JOB_MS ?? 15 * 60_000);
/** Storage usage above this fraction trips a disk-capacity alert. */
export const DISK_WARN_RATIO = Number(process.env.NXEON_DISK_WARN_RATIO ?? 0.85);
/** Node RAM usage above this fraction trips an alert. */
export const RAM_WARN_RATIO = Number(process.env.NXEON_RAM_WARN_RATIO ?? 0.9);
/** No fresh backup within this window ⇒ backups look stale. */
export const BACKUP_STALE_MS = Number(process.env.NXEON_BACKUP_STALE_MS ?? 48 * 60 * 60_000);
/** QUEUED backlog at/above this depth trips an alert. */
export const QUEUE_BACKLOG_ALERT = Number(process.env.NXEON_QUEUE_BACKLOG_ALERT ?? 25);

// ---- Small formatters ----------------------------------------------------

/** Compact human age from a millisecond duration. */
export function fmtAge(ms: number): string {
  if (ms < 0) ms = 0;
  const m = Math.floor(ms / 60_000);
  if (m < 1) return "just now";
  if (m < 60) return `${m}m`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h`;
  const d = Math.floor(h / 24);
  return `${d}d ${h % 24}h`;
}

// ---- Proxmox targets (read-only) ----------------------------------------

type PveTarget = {
  label: string;
  pveNode: string;
  get: (path: string, params?: Record<string, any>) => Promise<any>;
  /** Distinct storages worth watching on this node. */
  storages: string[];
};

/**
 * Resolve the set of Proxmox nodes to poll. Prefers explicit `Node` rows
 * (multi-node), and falls back to the env-configured primary when none exist.
 */
export async function nodeTargets(): Promise<PveTarget[]> {
  const nodes = await db.node.findMany({
    where: { enabled: true },
    orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
  });
  if (nodes.length === 0) {
    return [
      {
        label: primaryNode || "primary",
        pveNode: primaryNode,
        get: (p, pp) => pve.get(p, pp),
        storages: ["vmdata", "backup"],
      },
    ];
  }
  return nodes.map((n: Node) => {
    const client = pveFor({
      apiUrl: n.apiUrl,
      pveNode: n.pveNode,
      tokenId: n.tokenId,
      tokenSecret: n.tokenSecret,
    });
    const storages = [n.storageNvme, n.storageHdd, "backup"].filter(
      (v, i, a) => v && a.indexOf(v) === i
    );
    return { label: n.name, pveNode: n.pveNode, get: client.get, storages };
  });
}

export type StorageUsage = {
  node: string;
  storage: string;
  total: number;
  used: number;
  avail: number;
  ratio: number;
  reachable: boolean;
};

/** Per-node, per-storage disk usage (bytes). Unreachable storages are marked. */
export async function nodeStorageUsage(): Promise<StorageUsage[]> {
  const targets = await nodeTargets();
  const out: StorageUsage[] = [];
  for (const t of targets) {
    for (const storage of t.storages) {
      try {
        const st = await t.get(`/nodes/${t.pveNode}/storage/${storage}/status`);
        const total = Number(st?.total ?? 0);
        const used = Number(st?.used ?? 0);
        const avail = Number(st?.avail ?? Math.max(0, total - used));
        out.push({
          node: t.label,
          storage,
          total,
          used,
          avail,
          ratio: total > 0 ? used / total : 0,
          reachable: true,
        });
      } catch {
        out.push({ node: t.label, storage, total: 0, used: 0, avail: 0, ratio: 0, reachable: false });
      }
    }
  }
  return out;
}

export type NodeRam = {
  node: string;
  total: number;
  used: number;
  ratio: number;
  cpu: number;
  reachable: boolean;
};

/** Per-node RAM + CPU load from the node status endpoint. */
export async function nodeRamUsage(): Promise<NodeRam[]> {
  const targets = await nodeTargets();
  return Promise.all(
    targets.map(async (t) => {
      try {
        const s = await t.get(`/nodes/${t.pveNode}/status`);
        const total = Number(s?.memory?.total ?? 0);
        const used = Number(s?.memory?.used ?? 0);
        return {
          node: t.label,
          total,
          used,
          ratio: total > 0 ? used / total : 0,
          cpu: Number(s?.cpu ?? 0),
          reachable: true,
        };
      } catch {
        return { node: t.label, total: 0, used: 0, ratio: 0, cpu: 0, reachable: false };
      }
    })
  );
}

export type BackupSummary = {
  count: number;
  /** Unix seconds of the most recent backup (freshness signal). */
  newestCtime: number | null;
  /** Unix seconds of the oldest backup on disk. */
  oldestCtime: number | null;
  reachable: boolean;
};

/**
 * Summarise backups across all nodes' `backup` storage. Best-effort: if the
 * storage/content endpoint isn't available the node is simply skipped.
 */
export async function backupSummary(): Promise<BackupSummary> {
  const targets = await nodeTargets();
  let count = 0;
  let newest: number | null = null;
  let oldest: number | null = null;
  let reachable = false;
  for (const t of targets) {
    try {
      const items: any[] = await t.get(`/nodes/${t.pveNode}/storage/backup/content`, {
        content: "backup",
      });
      reachable = true;
      for (const b of items ?? []) {
        const ct = Number(b?.ctime ?? 0);
        if (!ct) continue;
        count++;
        if (newest === null || ct > newest) newest = ct;
        if (oldest === null || ct < oldest) oldest = ct;
      }
    } catch {
      // storage/content not available on this node — skip
    }
  }
  return { count, newestCtime: newest, oldestCtime: oldest, reachable };
}

// ---- Worker / job health -------------------------------------------------

export type StuckJob = {
  id: string;
  type: string;
  updatedAt: Date;
  attempts: number;
  serverId: string | null;
  hostname: string | null;
};

/** Jobs stuck in RUNNING past the stuck threshold. */
export async function stuckJobs(): Promise<StuckJob[]> {
  const rows = await db.job.findMany({
    where: { status: "RUNNING", updatedAt: { lt: new Date(Date.now() - STUCK_JOB_MS) } },
    orderBy: { updatedAt: "asc" },
    take: 20,
    select: {
      id: true,
      type: true,
      updatedAt: true,
      attempts: true,
      serverId: true,
      server: { select: { hostname: true } },
    },
  });
  return rows.map((r) => ({
    id: r.id,
    type: r.type,
    updatedAt: r.updatedAt,
    attempts: r.attempts,
    serverId: r.serverId,
    hostname: r.server?.hostname ?? null,
  }));
}

export type WorkerHealth = {
  status: CompStatus;
  detail: string;
  newestUpdatedAt: Date | null;
  stuckRunning: number;
  queuedBacklog: number;
  staleQueued: number;
};

/**
 * Worker liveness inferred from the Job queue:
 *  - QUEUED work older than WORKER_STALE_MS that hasn't been picked up ⇒ down
 *    (the loop isn't draining the queue).
 *  - Jobs stuck RUNNING past STUCK_JOB_MS ⇒ degraded.
 *  - Otherwise operational (an empty/fresh queue is healthy, even if idle).
 */
export async function workerHealth(): Promise<WorkerHealth> {
  const now = Date.now();
  const [newest, stuckRunning, queuedBacklog, staleQueued] = await Promise.all([
    db.job.findFirst({ orderBy: { updatedAt: "desc" }, select: { updatedAt: true } }),
    db.job.count({ where: { status: "RUNNING", updatedAt: { lt: new Date(now - STUCK_JOB_MS) } } }),
    db.job.count({ where: { status: "QUEUED" } }),
    db.job.count({ where: { status: "QUEUED", createdAt: { lt: new Date(now - WORKER_STALE_MS) } } }),
  ]);

  let status: CompStatus = "operational";
  let detail = newest
    ? `last job update ${fmtAge(now - newest.updatedAt.getTime())} ago`
    : "idle — no jobs processed yet";

  if (staleQueued > 0) {
    status = "down";
    detail = `${staleQueued} job(s) queued but not picked up — worker may be stopped`;
  } else if (stuckRunning > 0) {
    status = "degraded";
    detail = `${stuckRunning} job(s) stuck running > ${Math.round(STUCK_JOB_MS / 60_000)}m`;
  }

  return {
    status,
    detail,
    newestUpdatedAt: newest?.updatedAt ?? null,
    stuckRunning,
    queuedBacklog,
    staleQueued,
  };
}

// ---- Component health (db / proxmox) ------------------------------------

async function dbHealth(): Promise<Component> {
  try {
    await db.$queryRaw`SELECT 1`;
    return { status: "operational", detail: "responding" };
  } catch (e: any) {
    return { status: "down", detail: String(e?.message ?? e).slice(0, 120) };
  }
}

async function proxmoxHealth(): Promise<Component> {
  const targets = await nodeTargets();
  let ok = 0;
  let fail = 0;
  for (const t of targets) {
    try {
      await t.get(`/nodes/${t.pveNode}/status`);
      ok++;
    } catch {
      fail++;
    }
  }
  if (ok === 0) return { status: "down", detail: "no Proxmox node reachable" };
  if (fail > 0) return { status: "degraded", detail: `${fail} of ${ok + fail} nodes unreachable` };
  return { status: "operational", detail: `${ok} node(s) reachable` };
}

/** Full health report — the source of truth for /api/health and /status. */
export async function getHealth(): Promise<HealthReport> {
  const [dbc, wh, px] = await Promise.all([dbHealth(), workerHealth(), proxmoxHealth()]);
  return {
    web: { status: "operational", detail: "serving requests" },
    db: dbc,
    worker: { status: wh.status, detail: wh.detail },
    proxmox: px,
    checkedAt: new Date().toISOString(),
  };
}

/** Roll the four components up into a single worst-of status. */
export function overallStatus(h: HealthReport): CompStatus {
  const all = [h.web, h.db, h.worker, h.proxmox].map((c) => c.status);
  if (all.includes("down")) return "down";
  if (all.includes("degraded")) return "degraded";
  return "operational";
}

import { NextResponse } from "next/server";
import { getHealth, type HealthReport } from "@/lib/monitoring";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

/**
 * GET /api/health — public, unauthenticated health probe.
 *
 * Returns { web, db, worker, proxmox } where each is
 * { status: "operational" | "degraded" | "down", detail }. Safe to expose:
 * no secrets, no per-customer data — just component states.
 *
 * Cached ~15s in-process so external monitors / the status page don't hammer
 * the DB and Proxmox on every request.
 */

const TTL_MS = 15_000;
let cache: { at: number; body: HealthReport } | null = null;

export async function GET() {
  try {
    if (!cache || Date.now() - cache.at > TTL_MS) {
      cache = { at: Date.now(), body: await getHealth() };
    }
    const worstDown =
      cache.body.db.status === "down" || cache.body.proxmox.status === "down";
    return NextResponse.json(cache.body, {
      status: worstDown ? 503 : 200,
      headers: { "Cache-Control": "public, max-age=15, s-maxage=15" },
    });
  } catch (e: any) {
    return NextResponse.json(
      { error: "health check failed", detail: String(e?.message ?? e).slice(0, 160) },
      { status: 500 }
    );
  }
}

import { db } from "../lib/db";
import {
  nodeStorageUsage,
  nodeRamUsage,
  backupSummary,
  stuckJobs,
  workerHealth,
  fmtAge,
  DISK_WARN_RATIO,
  RAM_WARN_RATIO,
  BACKUP_STALE_MS,
  QUEUE_BACKLOG_ALERT,
  STUCK_JOB_MS,
} from "../lib/monitoring";

/**
 * Monitoring sweep — run periodically from the worker loop. Read-only checks
 * that raise dashboard notifications for all ADMINs when a threshold trips.
 *
 * Notifications are de-duplicated by title within a rolling window so a
 * persistent condition (e.g. a node stuck at 90% disk) alerts once every few
 * hours rather than every sweep.
 */

const DEDUPE_HOURS = Number(process.env.NXEON_ALERT_DEDUPE_HOURS ?? 3);

/**
 * Fan a single alert out to every ADMIN, unless an identically-titled alert
 * already went out within the dedupe window.
 */
async function notifyAdmins(
  title: string,
  body: string,
  href = "/admin/monitoring"
): Promise<void> {
  const since = new Date(Date.now() - DEDUPE_HOURS * 60 * 60_000);
  const recent = await db.notification.findFirst({
    where: { title, createdAt: { gt: since } },
    select: { id: true },
  });
  if (recent) return;

  const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
  if (admins.length === 0) return;

  await db.notification.createMany({
    data: admins.map((a) => ({ userId: a.id, title, body, href })),
  });
}

export async function monitorSweep(): Promise<void> {
  // 1. Node disk usage > threshold
  try {
    const storage = await nodeStorageUsage();
    for (const s of storage) {
      if (s.reachable && s.total > 0 && s.ratio > DISK_WARN_RATIO) {
        const pct = Math.round(s.ratio * 100);
        await notifyAdmins(
          `Disk capacity warning — ${s.node}/${s.storage} at ${pct}%`,
          `Storage "${s.storage}" on node ${s.node} is ${pct}% full ` +
            `(${(s.avail / 1024 ** 3).toFixed(0)} GB free). Free space or add capacity to keep provisioning healthy.`
        );
      }
    }
  } catch (e) {
    console.error("[monitor] disk check error", e);
  }

  // 2. Node RAM pressure > threshold
  try {
    const ram = await nodeRamUsage();
    for (const r of ram) {
      if (r.reachable && r.total > 0 && r.ratio > RAM_WARN_RATIO) {
        const pct = Math.round(r.ratio * 100);
        await notifyAdmins(
          `Memory pressure — ${r.node} at ${pct}%`,
          `Node ${r.node} RAM is ${pct}% used. New deploys may be refused until usage drops.`
        );
      }
    }
  } catch (e) {
    console.error("[monitor] ram check error", e);
  }

  // 3. Stuck jobs (RUNNING beyond the stuck threshold)
  try {
    const stuck = await stuckJobs();
    if (stuck.length > 0) {
      const mins = Math.round(STUCK_JOB_MS / 60_000);
      const lines = stuck
        .slice(0, 8)
        .map(
          (j) =>
            `• ${j.type}${j.hostname ? ` (${j.hostname})` : ""} — running ${fmtAge(
              Date.now() - j.updatedAt.getTime()
            )}`
        )
        .join("\n");
      await notifyAdmins(
        `Stuck jobs — ${stuck.length} running > ${mins}m`,
        `The worker has job(s) stuck in RUNNING:\n${lines}`
      );
    }
  } catch (e) {
    console.error("[monitor] stuck-job check error", e);
  }

  // 4. Worker liveness + pending-job backlog
  try {
    const wh = await workerHealth();
    if (wh.status === "down") {
      await notifyAdmins(
        "Worker appears stopped",
        wh.detail + ". Check the provisioning worker process."
      );
    }
    if (wh.queuedBacklog >= QUEUE_BACKLOG_ALERT) {
      await notifyAdmins(
        `Job backlog building — ${wh.queuedBacklog} queued`,
        `${wh.queuedBacklog} jobs are waiting in the queue. The worker may be overloaded or slow.`
      );
    }
  } catch (e) {
    console.error("[monitor] worker check error", e);
  }

  // 5. Backup freshness (best-effort; skipped if backup storage isn't listable)
  try {
    const bk = await backupSummary();
    if (bk.reachable && bk.count > 0 && bk.newestCtime !== null) {
      const ageMs = Date.now() - bk.newestCtime * 1000;
      if (ageMs > BACKUP_STALE_MS) {
        await notifyAdmins(
          `Backups look stale — newest is ${fmtAge(ageMs)} old`,
          `The most recent backup on disk is ${fmtAge(ageMs)} old. Verify the backup schedule is running.`
        );
      }
    }
  } catch (e) {
    console.error("[monitor] backup check error", e);
  }
}

