export const HOST_RAM_MB = Number(process.env.NXEON_HOST_RAM_MB ?? 64000);
export const HOST_RAM_RESERVE_MB = Number(process.env.NXEON_HOST_RAM_RESERVE_MB ?? 8000);
export const RAM_OVERSELL_FACTOR = Number(process.env.NXEON_RAM_OVERSELL ?? 1.5);

/**
 * Usable NVMe VM-disk pool in GB, used as a fallback when the live Proxmox
 * storage total can't be read. Unlike RAM we do NOT oversell disk — thin
 * provisioning already lets guests share the pool, so we commit against the
 * real pool size minus a safety margin.
 */
export const HOST_DISK_GB = Number(process.env.NXEON_HOST_DISK_GB ?? 800);
/** Fraction of usable disk we allow to be committed before refusing deploys. */
export const DISK_SAFETY_RATIO = Number(process.env.NXEON_DISK_SAFETY ?? 0.9);

