import type { Metadata } from "next";
import { MarketingHeader } from "@/components/marketing/MarketingHeader";
import { MarketingFooter } from "@/components/marketing/MarketingFooter";
import { getHealth, overallStatus, type CompStatus } from "@/lib/monitoring";

const APP_URL = process.env.APP_URL ?? "https://revsports.ca";

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "System Status",
  description:
    "Live operational status of the Nxeon platform — web dashboard, provisioning, automation and databases.",
  alternates: { canonical: "/status" },
  openGraph: {
    type: "website",
    title: "Nxeon System Status",
    description: "Live operational status of the Nxeon platform.",
    url: `${APP_URL}/status`,
  },
};

const STATUS_META: Record<CompStatus, { label: string; dot: string; text: string; pulse?: boolean }> = {
  operational: { label: "Operational", dot: "bg-emerald-400", text: "text-emerald-400", pulse: true },
  degraded: { label: "Degraded performance", dot: "bg-amber-400", text: "text-amber-400", pulse: true },
  down: { label: "Outage", dot: "bg-red-400", text: "text-red-400", pulse: true },
};

const OVERALL_META: Record<CompStatus, { title: string; ring: string; border: string; dot: string }> = {
  operational: {
    title: "All systems operational",
    ring: "bg-emerald-500/15",
    border: "border-emerald-500/20 bg-emerald-500/[0.06]",
    dot: "bg-emerald-400",
  },
  degraded: {
    title: "Some systems are degraded",
    ring: "bg-amber-500/15",
    border: "border-amber-500/20 bg-amber-500/[0.06]",
    dot: "bg-amber-400",
  },
  down: {
    title: "We're experiencing an outage",
    ring: "bg-red-500/15",
    border: "border-red-500/20 bg-red-500/[0.06]",
    dot: "bg-red-400",
  },
};

// Public-facing component labels. We deliberately show friendly names and NOT
// the internal `detail` strings, which can carry operational specifics.
const COMPONENT_META: { key: "web" | "proxmox" | "worker" | "db"; name: string; description: string }[] = [
  { key: "web", name: "Web & Dashboard", description: "Marketing site, customer portal and admin console" },
  { key: "proxmox", name: "Provisioning & Compute", description: "Hypervisor, server creation, power and resize actions" },
  { key: "worker", name: "Automation & Jobs", description: "Provisioning worker, backups and scheduled tasks" },
  { key: "db", name: "Platform Database", description: "Accounts, billing and server records" },
];

export default async function StatusPage() {
  const health = await getHealth();
  const overall = overallStatus(health);
  const om = OVERALL_META[overall];

  const checkedAt = new Date(health.checkedAt).toLocaleString("en-US", {
    dateStyle: "medium",
    timeStyle: "short",
