            <div className={`card flex items-center gap-4 ${om.border}`}>
              <span className={`relative flex h-11 w-11 shrink-0 items-center justify-center rounded-full ${om.ring}`}>
                <span className={`h-3 w-3 rounded-full ${om.dot} animate-pulse-dot`} />
              </span>
              <div>
                <h1 className="text-xl font-bold tracking-tight text-white">{om.title}</h1>
                <p className="mt-0.5 text-sm text-slate-400">Last checked {checkedAt} UTC</p>
              </div>
            </div>
          </div>
        </section>

        {/* Components */}
        <section className="mx-auto max-w-4xl px-5 py-10 sm:px-6">
          <h2 className="section-label mb-3">Components</h2>
          <div className="card divide-y divide-white/[0.06] p-0">
            {COMPONENT_META.map((c) => {
              const status = health[c.key].status;
              const meta = STATUS_META[status];
              return (
                <div key={c.key} className="flex items-center justify-between gap-4 px-6 py-5">
                  <div>
                    <p className="font-medium text-white">{c.name}</p>
                    <p className="mt-0.5 text-sm text-slate-400">{c.description}</p>
                  </div>
                  <span className={`inline-flex shrink-0 items-center gap-2 text-sm font-medium ${meta.text}`}>
                    <span className={`h-2.5 w-2.5 rounded-full ${meta.dot} ${meta.pulse ? "animate-pulse-dot" : ""}`} />
                    {meta.label}
                  </span>
                </div>
              );
            })}
          </div>
        </section>

        {/* Note */}
        <section className="mx-auto max-w-4xl px-5 pb-24 sm:px-6">
          <div className="card border-dashed">
            <p className="text-sm leading-relaxed text-slate-400">
              <span className="font-medium text-slate-200">About this page.</span> Component
              states above are checked live against the Nxeon platform and refresh roughly every 15
              seconds. For an active incident affecting your service, or help with your own server,
              open a ticket from your{" "}
              <a href="/dashboard" className="text-brand-300 hover:text-brand-200">
                dashboard
              </a>
              .
            </p>
          </div>
        </section>
      </main>
      <MarketingFooter />
    </div>
  );
}

